/// The world, about the print the machine is running when it runs one.
///
/// The policy refuses an action against an ended print before it asks whether
/// the actor may request it at all, so a refusal for the grant is asked of the
/// print the machine is running rather than of one a read has ended.
fn about_the_running_print(
    client: &Client,
    world: supervisor::Supervisor,
) -> supervisor::Supervisor {
    match client.prints().expect("a listing is answered").active {
        Some(print_id) => supervisor::Supervisor { print_id, ..world },
        None => world,
    }
}

/// Every method, answered by a real supervisor, in the one order it admits.
#[test]
fn every_method_is_answered_by_a_real_supervisor() {
    let root = tempfile::tempdir().expect("this walk's own root");
    let mut standing = supervisor::standing(root.path(), false);
    let world = standing.at.clone();
    let proxy = live::Proxy::in_front_of(&world.server);
    let client = Client::new(proxy.url(), Actor::Operator).with_credential(&*world.credential);
    let manifest = manifest(&world.file_name);

    step_status(&client, &world, &proxy);
    step_context(&client, &world, &proxy);
    step_image(&client, &world, &proxy);
    step_manifest_set(&client, &world, &proxy, &manifest);
    step_manifest_get(&client, &world, &proxy);
    step_history(&client, &world, &proxy);
    step_events(&client, &world, &proxy);
    step_look(&client, &world, &proxy);
    step_cancel(&client, &world, &proxy);
    let world = step_start_print(&client, &world, &proxy, &manifest);
    step_set_feedrate_factor(&client, &world, &proxy);
    step_set_flowrate_factor(&client, &world, &proxy);
    step_set_fan_percent(&client, &world, &proxy);
    step_set_tool_target_c(&client, &world, &proxy);
    step_set_bed_target_c(&client, &world, &proxy);
    step_acknowledge_failure(&client, &world, &proxy);
    step_pause(&client, &world, &proxy);
    step_resume(&client, &world, &proxy);
    step_spools(&client, &world, &proxy);
    step_spool(&client, &world, &proxy);
    step_printer_history(&client, &world, &proxy);
    step_preflight(&client, &world, &proxy);
    step_register_spool(&client, &world, &proxy);
    step_load_spool(&client, &world, &proxy);
    step_unload_spool(&client, &world, &proxy);
    step_adjust_spool(&client, &world, &proxy);
    step_retire_spool(&client, &world, &proxy);
    step_prints(&client, &world, &proxy);

    assert!(proxy.calls() >= 28, "every call went through the proxy");
    standing.stop();
}

/// Every action, refused by a real supervisor's own policy, as a typed rejection.
///
/// One client acting as the operator — the one identity its credential is —
/// against a supervisor whose envelope grants the operator nothing, about the
/// print its machine is running. The policy takes that decision before it
/// looks at the state, the interval or the bounds, so every action is refused
/// from wherever the machine happens to be, and nothing moves.
#[test]
fn every_action_is_refused_as_a_typed_rejection_by_a_real_supervisor() {
    let root = tempfile::tempdir().expect("this walk's own root");
    let mut standing = supervisor::standing(root.path(), true);
    let world = standing.at.clone();
    let proxy = live::Proxy::in_front_of(&world.server);
    let client = Client::new(proxy.url(), Actor::Operator).with_credential(&*world.credential);
    let manifest = manifest(&world.file_name);
    let world = about_the_running_print(&client, world);

    refused_cancel(&client, &world, &proxy);
    refused_start_print(&client, &world, &proxy, &manifest);
    refused_set_feedrate_factor(&client, &world, &proxy);
    refused_set_flowrate_factor(&client, &world, &proxy);
    refused_set_fan_percent(&client, &world, &proxy);
    refused_set_tool_target_c(&client, &world, &proxy);
    refused_set_bed_target_c(&client, &world, &proxy);
    refused_acknowledge_failure(&client, &world, &proxy);
    refused_pause(&client, &world, &proxy);
    refused_resume(&client, &world, &proxy);
    refused_register_spool(&client, &world, &proxy);
    refused_load_spool(&client, &world, &proxy);
    refused_unload_spool(&client, &world, &proxy);
    refused_adjust_spool(&client, &world, &proxy);
    refused_retire_spool(&client, &world, &proxy);

    standing.stop();
}
